/* engines/jplayer.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /* jPlayer is loaded lazily together with its pinned jQuery dependency. The
     same createElement shim hands it the shared audio element. */
  async function createJPlayer(url, startAt, autoplay) {
    try { await P.loadJPlayerScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.jQuery?.fn?.jPlayer) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.showEngineUi("jplayer");
    try {
      const media = P.$("labJPlayerMedia");
      P.jplayerHost = P.$("labJPlayer");
      if (media && !media.dataset.jplayerReady) {
        const position = P.rememberAudioDom();
        P.withSharedAudioElement(() => {
          window.jQuery(media).jPlayer({
            supplied: "mp3",
            preload: "auto",
            loop: false,
            cssSelectorAncestor: "#jp_container_1",
            errorAlerts: false,
            warningAlerts: false,
          });
        });
        media.dataset.jplayerReady = "true";
        P.restoreAudioDom(position);
      }
      window.jQuery(media).jPlayer("setMedia", { mp3: url });
    } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (startAt) P.setTime(startAt);
    if (autoplay) P.attemptPlay();
    return true;
  }
  Object.assign(P, { createJPlayer });
}
